const PHASES=[['链盘输料','链盘沿闭环料线运行，各料筒逐步补料。'],['定量储料','末端料位到达设定，停止输料，关闭球保持落座。'],['统一放料','拉绳抬起关闭球，饲料经落料管进入食槽。'],['复位完成','关闭球重新落座，等待下一次补料。']];
let viewer,selected='system',fallback={progress:0,portion:4,station:0,playing:false,view:'system',xray:false,labels:true,speed:1,lesson:'explore',lessonStep:0,lessonProgress:0,lessonPlaying:false,pigsVisible:true};
const state=()=>viewer||fallback;
function describe(part){selected=part;const c=COPY[part];$('#detail-kicker').textContent=c.kicker;$('#detail-title').textContent=c.title;$('#detail-description').textContent=c.description;$('#detail-fact').replaceChildren();const a=document.createElement('span'),b=document.createElement('strong');a.textContent=c.fact[0];b.textContent=c.fact[1];$('#detail-fact').append(a,b);$('#detail-note').textContent=c.note;const index=Object.keys(COPY).indexOf(part);$('#component-counter').textContent=`${String(index+1).padStart(2,'0')} / 06`;$$('[data-part]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.part===part)));}
function select(part,station){if(!COPY[part])return;if(state().lesson!=='explore'){if(viewer)viewer.focusPart?.(part,station);return;}describe(part);const v=state();if(Number.isInteger(station)&&station>=0&&station<12)v.station=station;if(viewer)viewer.select(part,v.station);$('#station').value=String(v.station);sync();}
function setView(view){if(state().lesson!=='explore')setLesson('explore');if(!['system','dispenser','principle'].includes(view))throw Error('Unknown view');const v=state();if(view==='system'){v.part='system';describe('system');}else{v.part=view==='principle'?'release':'dispenser';describe(v.part);}if(viewer)viewer.setView(view);else v.view=view;sync();}
function seek(t){if(state().lesson!=='explore')setLesson('explore');const v=state();v.playing=false;if(viewer)viewer.setProgress(t);else v.progress=t;sync();}
function play(){if(!viewer)return;if(viewer.lesson!=='explore')setLesson('explore');const v=viewer;if(v.progress>=1)v.setProgress(0);v.playing=!v.playing;if(v.playing){v.xray=true;v.lastTime=0;}v.dirty=true;sync();}
function setPortion(n){if(typeof n!=='number'||!Number.isFinite(n)||n<1||n>6||Math.abs(n*2-Math.round(n*2))>1e-7)throw Error('容积必须为 1–6 L，步长 0.5 L');const v=state();v.portion=n;if(lessonFor(v)?.effect==='dose'){v.lessonProgress=1;v.lessonPlaying=false;}v.dirty=true;$('#portion').value=n;sync();}
let tutorialSignature='';
function setLesson(mode,index=0){const group=LESSONS[mode];if(mode!=='explore'&&!group)throw Error('Unknown lesson');if(group&&(!Number.isInteger(index)||index<0||index>=group.steps.length))throw Error('Invalid step');if(viewer)viewer.setLesson(mode,index);else{Object.assign(fallback,{lesson:mode,lessonStep:index,lessonProgress:0,lessonPlaying:false,playing:false});const step=lessonFor(fallback);if(step){fallback.view=step.view;fallback.part=step.part;fallback.progress=lessonCycle(fallback);}else{fallback.view='system';fallback.progress=0;}}if(mode==='explore')describe('system');sync();}
function syncLesson(v){const step=lessonFor(v),active=!!step;$('.stage').dataset.lesson=v.lesson;$('.inspector').dataset.lesson=v.lesson;$('#explore-panel').hidden=active;$('#lesson-panel').hidden=!active;$('#cycle-controls').hidden=active;$('#lesson-controls').hidden=!active;$('#lesson-scene-note').hidden=!active;$$('[data-lesson]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lesson===v.lesson)));$('#toggle-pigs').textContent=v.pigsVisible?'隐藏猪':'显示猪';$('#toggle-pigs').setAttribute('aria-pressed',String(v.pigsVisible));$('#toggle-pigs').title='整机视角显示或隐藏栏内的猪；单筒特写自动省略';if(!active)return;const group=LESSONS[v.lesson],signature=v.lesson+':'+v.lessonStep;if(signature!==tutorialSignature){$('#lesson-group-title').textContent=group.title;$('#lesson-step-list').replaceChildren();group.steps.forEach((item,i)=>{const b=document.createElement('button'),num=document.createElement('b'),name=document.createElement('span');num.textContent=String(i+1).padStart(2,'0');name.textContent=item.short;b.append(num,name);b.setAttribute('aria-current',i===v.lessonStep?'step':'false');b.addEventListener('click',()=>setLesson(v.lesson,i));$('#lesson-step-list').append(b);});$('#lesson-title').textContent=step.title;$('#lesson-text').textContent=step.text;$('#lesson-check').textContent=step.check;$('#lesson-caution').textContent=step.note;$('#lesson-source').href=step.url;$('#lesson-count').textContent=`${v.lessonStep+1} / ${group.steps.length}`;$('#lesson-scene-note').textContent=`${group.title} ${String(v.lessonStep+1).padStart(2,'0')} / ${String(group.steps.length).padStart(2,'0')} · ${step.short}`;tutorialSignature=signature;}$('#lesson-prev').disabled=v.lessonStep===0;$('#lesson-next').textContent=v.lessonStep===group.steps.length-1?'返回总览':'下一步';$('#lesson-play').disabled=!viewer;$('#lesson-play').textContent=v.lessonPlaying?'暂停演示':v.lessonProgress>=1?'重新演示':step.action;$('#lesson-progress').value=Math.round(v.lessonProgress*1000);$('#lesson-percent').textContent=Math.round(v.lessonProgress*100)+'%';$('#lesson-control-hint').textContent=v.lessonProgress>=1?'本步演示完成，可继续下一步':'可暂停、拖动进度，或点击标注查看局部';$('#station').disabled=step.station!==undefined;$('#station').value=String(v.station);}
let labelSignature='',labels=new Map();
function renderLabels(v){if(!viewer)return;const list=viewer.annotations(),signature=v.lesson+':'+v.lessonStep+':'+list.map(x=>x.id).join('|');if(signature!==labelSignature){$('#labels').replaceChildren();labels.clear();for(const l of list){const b=document.createElement('button');b.className='scene-label';b.dataset.label=l.id;b.addEventListener('click',()=>{const item=b.currentLabel||l;if(item.lesson){viewer.focusPoint(item.p);return;}if(viewer.view!=='system'&&item.id!=='inlet'){describe(item.part);viewer.part=item.part;viewer.dirty=true;sync();}else select(item.part,item.station);});$('#labels').append(b);labels.set(l.id,b);}labelSignature=signature;}const occupied=[];for(const l of list){const b=labels.get(l.id);b.currentLabel=l;b.textContent=l.text;b.classList.toggle('selected',l.selected);b.classList.toggle('lesson-label',!!l.lesson);const w=Math.min(l.text.length*13+25,220),h=32;if(!l.visible||l.x<0||l.x>v.width||l.y<0||l.y>v.height){b.hidden=true;continue;}let x=Math.max(w/2+12,Math.min(v.width-w/2-12,l.x)),y=Math.max(192,Math.min(v.height-130,l.y-18));for(let tries=0;tries<6;tries++){const collision=occupied.find(r=>Math.abs(x-r.x)<(w+r.w)/2+8&&Math.abs(y-r.y)<h+7);if(!collision)break;y=collision.y+h+8;}if(y>v.height-130){b.hidden=true;continue;}b.hidden=false;b.style.left=`${x}px`;b.style.top=`${y}px`;occupied.push({x,y,w});}}
function sync(){const v=state();if(v.lesson!=='explore')v.progress=lessonCycle(v);const c=cycleAt(v.progress,v.station,v.portion);if(lessonFor(v)?.effect==='dose')c.litres=1+(v.portion-1)*v.lessonProgress;syncLesson(v);if(v.lesson==='explore')$('#station').disabled=false;$('#portion-value').innerHTML=`${v.portion.toFixed(1)} <small>L</small>`;$('#fill-value').innerHTML=`${c.litres.toFixed(1)} <small>L</small>`;$('#outlet-value').textContent=c.outlet?'打开':'关闭';$('#play-icon').textContent=v.playing?'Ⅱ':'▶';$('#play-label').textContent=v.playing?'暂停演示':v.progress>=1?'重新播放':v.progress>0?'继续播放':'播放饲喂循环';$('#progress').value=Math.round(v.progress*1000);$('#phase-title').textContent=v.progress===0?'准备上料':PHASES[c.phase][0];$('#phase-description').textContent=v.progress===0?'点击播放，跟随饲料走完整个系统。':PHASES[c.phase][1];$$('[data-time]').forEach((el,i)=>el.classList.toggle('active',i===c.phase));$$('[data-view]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.view===v.view)));$('#toggle-shell').setAttribute('aria-pressed',String(v.xray));$('#toggle-labels').setAttribute('aria-pressed',String(v.labels));$('#scene-caption').textContent=v.view==='system'?'12 个饲喂位 · 双排料线':`${STATIONS[v.station].name} · 6 L 级定量料筒示意`;renderLabels(v);}
try{viewer=new FeedingViewer($('#scene'),select,sync);}catch(error){console.error('3D scene unavailable',error);$('#scene-error').hidden=false;$('#play').disabled=true;$('#play-label').textContent='三维暂不可用';}
$$('[data-part]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.part)));$$('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$$('[data-time]').forEach(b=>b.addEventListener('click',()=>seek(Number(b.dataset.time))));$('#station').addEventListener('change',e=>{const v=state();if(v.lesson==='explore')select('dispenser',Number(e.target.value));else{v.station=Number(e.target.value);viewer?.frame();v.dirty=true;sync();}});$('#portion').addEventListener('input',e=>setPortion(Number(e.target.value)));$('#progress').addEventListener('input',e=>seek(Number(e.target.value)/1000));$('#play').addEventListener('click',play);$('#reset').addEventListener('click',()=>seek(0));$('#speed').addEventListener('change',e=>{state().speed=Number(e.target.value);});$('#home').addEventListener('click',()=>viewer?.frame());$('#zoom-in').addEventListener('click',()=>viewer?.zoom(.83));$('#zoom-out').addEventListener('click',()=>viewer?.zoom(1.2));$('#toggle-shell').addEventListener('click',()=>{const v=state();v.xray=!v.xray;v.dirty=true;sync();});$('#toggle-labels').addEventListener('click',()=>{const v=state();v.labels=!v.labels;v.dirty=true;sync();});$('#open-sources').addEventListener('click',()=>$('#sources').showModal());$('#close-sources').addEventListener('click',()=>$('#sources').close());$('#sources').addEventListener('click',e=>{if(e.target===$('#sources')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#reload').addEventListener('click',()=>location.reload());
$$('[data-lesson]').forEach(b=>b.addEventListener('click',()=>setLesson(b.dataset.lesson)));
$('#lesson-prev').addEventListener('click',()=>{const v=state();if(v.lessonStep>0)setLesson(v.lesson,v.lessonStep-1);});
$('#lesson-next').addEventListener('click',()=>{const v=state();if(v.lessonStep<LESSONS[v.lesson].steps.length-1)setLesson(v.lesson,v.lessonStep+1);else setLesson('explore');});
$('#lesson-play').addEventListener('click',()=>{viewer?.toggleLesson();sync();});
$('#lesson-progress').addEventListener('input',e=>{const n=Number(e.target.value)/1000;if(viewer)viewer.setLessonProgress(n);else fallback.lessonProgress=n;sync();});
$('#toggle-pigs').addEventListener('click',()=>{const v=state();v.pigsVisible=!v.pigsVisible;v.dirty=true;sync();});sync();
