if(document.modelContext?.registerTool){const life=new AbortController();addEventListener('pagehide',()=>life.abort(),{once:true});const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});}catch{}};register({name:'inspect_feeding_system',title:'查看饲喂系统状态',description:'读取当前视角、料筒、演示容积、进度和出口状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>{const v=state(),c=cycleAt(v.progress,v.station,v.portion);return{view:v.view,station:STATIONS[v.station].name,portionLitres:v.portion,progress:v.progress,playing:v.playing,lesson:v.lesson,lessonStep:v.lessonStep+1,lessonProgress:v.lessonProgress,pigsVisible:v.pigsVisible,storedLitres:c.litres,outletOpen:c.outlet,schematic:true};}});register({name:'configure_feeding_demo',title:'配置饲喂演示',description:'切换整机或单筒视角，设定演示容积并定位循环进度；不操作真实设备。',inputSchema:{type:'object',properties:{view:{type:'string',enum:['system','dispenser','principle']},portionLitres:{type:'number',minimum:1,maximum:6,multipleOf:.5},progress:{type:'number',minimum:0,maximum:1}},additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected an object');const allowed=['view','portionLitres','progress'];if(Object.keys(input).some(k=>!allowed.includes(k)))throw Error('Unknown input');if(input.view!==undefined&&!['system','dispenser','principle'].includes(input.view))throw Error('Invalid view');if(input.portionLitres!==undefined&&(typeof input.portionLitres!=='number'||!Number.isFinite(input.portionLitres)||input.portionLitres<1||input.portionLitres>6||input.portionLitres*2%1))throw Error('Invalid portion');if(input.progress!==undefined&&(typeof input.progress!=='number'||!Number.isFinite(input.progress)||input.progress<0||input.progress>1))throw Error('Invalid progress');if(input.view!==undefined)setView(input.view);if(input.portionLitres!==undefined)setPortion(input.portionLitres);if(input.progress!==undefined)seek(input.progress);await new Promise(r=>requestAnimationFrame(r));const v=state();return{view:v.view,portionLitres:v.portion,progress:v.progress};}});}
